// @vitest-environment node
//
// The team-names construction (design §4.2) against vectors/team-names-v1.json: ten seals of the
// full construction over two teams (one-byte, short, long, two-, three- and four-byte UTF-8, 300
// and 400 bytes), every identity's envelope under its vault key, every row's name tag, and the
// negative vectors for each binding. The file was generated by a standard-library Go reference that
// reproduces RFC 9180 A.3.1, A.3.3, A.6.1 and A.6.3, and every seal in it equals what Cloudflare
// CIRCL's independent HPKE produces for the same inputs; the server carries the same file, pinned by
// the same SHA-256, so a drift fails on both sides.

import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { vaultOpsFor, type VaultKey } from '@ciphera-net/tessera'
import { importPrivateKey, importPublicKey } from '../hpke'
import {
  IDENTITY_CONTEXT,
  IDENTITY_ENVELOPE_SIZE,
  INFO_LABEL,
  MAX_NAME_BYTES,
  PADDED_SIZE,
  SEALED_SIZE,
  TAG_LABEL,
  TEAM_NAMES_SUITE,
  WIRE_VERSION,
  cleanName,
  createIdentity,
  importTagKey,
  keyIdOf,
  nameFoldKey,
  nameInfo,
  nameTag,
  openIdentityEnvelope,
  openName,
  padName,
  sealName,
  sealNameWithEphemeralKeyForTesting,
  shareableName,
  unpadName,
  uuidBytes,
  type TeamIdentity,
} from '../team-names'
import { TeamNamesError } from '@/lib/team-names/errors'

const FILE = fileURLToPath(new URL('./vectors/team-names-v1.json', import.meta.url))
const FILE_SHA256 = '184e02fd21842b29a1faf233732aef7f5910793c732f3c5f12601a665f60ae37'

interface VIdentity {
  label: string
  user_id: string
  private_key: string
  public_key: string
  key_id: string
  tag_secret: string
  vmk: string
  envelope_context: string
  envelope_plaintext: string
  sealed_private_key: string
}
interface VSeal {
  description: string
  team_id: string
  sender: string
  recipient: string
  sender_id: string
  recipient_id: string
  name: string
  name_utf8: string
  plaintext: string
  info: string
  aad: string
  ephemeral_private_key: string
  enc: string
  shared_secret: string
  key: string
  base_nonce: string
  sealed: string
  sender_key_id: string
  recipient_key_id: string
  name_tag: string
}
interface VOpenNegative {
  description: string
  team_id: string
  sender_id: string
  recipient_id: string
  opener: string
  sender_public_key: string
  sealed: string
  outcome: 'open_fails' | 'refused_version' | 'refused_length' | 'no_name'
}
interface VTagNegative {
  description: string
  row: number
  tag_secret: string
  name: string
  recipient_key_id: string
  enc: string
}
interface VEnvelopeNegative {
  description: string
  envelope_of: string
  vmk: string
  context: string
}

const v = JSON.parse(readFileSync(FILE, 'utf8')) as {
  suite: { kem_id: number; kdf_id: number; aead_id: number }
  info_label: string
  tag_label: string
  identity_context: string
  wire_version: number
  padded_size: number
  max_name_bytes: number
  sealed_size: number
  identities: VIdentity[]
  seals: VSeal[]
  open_negatives: VOpenNegative[]
  tag_negatives: VTagNegative[]
  envelope_negatives: VEnvelopeNegative[]
}

const hex = (s: string) => Uint8Array.from(Buffer.from(s, 'hex'))
const toHex = (b: Uint8Array) => Buffer.from(b).toString('hex')

async function vaultKey(vmkHex: string): Promise<VaultKey> {
  return (await crypto.subtle.importKey('raw', hex(vmkHex), 'HKDF', false, ['deriveKey'])) as VaultKey
}

const identityCache = new Map<string, Promise<TeamIdentity>>()
function identity(label: string): Promise<TeamIdentity> {
  const cached = identityCache.get(label)
  if (cached) return cached
  const vi = v.identities.find((i) => i.label === label)
  if (!vi) throw new Error(`no identity ${label}`)
  const made = (async () => openIdentityEnvelope(vaultOpsFor(await vaultKey(vi.vmk)), hex(vi.sealed_private_key)))()
  identityCache.set(label, made)
  return made
}
const byLabel = (label: string) => v.identities.find((i) => i.label === label) as VIdentity

afterEach(() => {
  vi.restoreAllMocks()
})

describe('the team-names-v1 vector file', () => {
  it('is the pinned file, and its constants are this code’s', () => {
    expect(createHash('sha256').update(readFileSync(FILE)).digest('hex')).toBe(FILE_SHA256)
    expect(v.suite).toEqual({ kem_id: TEAM_NAMES_SUITE.kemId, kdf_id: TEAM_NAMES_SUITE.kdfId, aead_id: TEAM_NAMES_SUITE.aeadId })
    expect([v.info_label, v.tag_label, v.identity_context]).toEqual([INFO_LABEL, TAG_LABEL, IDENTITY_CONTEXT])
    expect([v.wire_version, v.padded_size, v.max_name_bytes, v.sealed_size]).toEqual([WIRE_VERSION, PADDED_SIZE, MAX_NAME_BYTES, SEALED_SIZE])
    expect(v.seals).toHaveLength(10)
    expect(new Set(v.seals.map((s) => s.team_id)).size).toBe(2)
  })
})

describe('identities and their envelopes', () => {
  it.each(v.identities.map((i) => [i.label, i] as const))('%s: the envelope opens under the vault key to 0x01 || d || pub || tag_secret', async (_l, vi) => {
    const vault = vaultOpsFor(await vaultKey(vi.vmk))
    const pt = await vault.open(IDENTITY_CONTEXT, hex(vi.sealed_private_key))
    expect(toHex(pt)).toBe(vi.envelope_plaintext)
    expect(toHex(pt)).toBe(`01${vi.private_key}${vi.public_key}${vi.tag_secret}`)
    expect(hex(vi.sealed_private_key).length).toBe(IDENTITY_ENVELOPE_SIZE)
  })

  it.each(v.identities.map((i) => [i.label, i] as const))('%s: the session identity carries the pub, the key id and a non-extractable key', async (label, vi) => {
    const id = await identity(label)
    expect(toHex(id.publicKey)).toBe(vi.public_key)
    expect(toHex(id.keyId)).toBe(vi.key_id)
    expect(toHex(await keyIdOf(hex(vi.public_key)))).toBe(vi.key_id)
    expect(id.privateKey.extractable).toBe(false)
    expect(id.privateKey.usages).toEqual(['deriveBits'])
  })

  it('pairs each envelope’s d with its pub (two Diffie-Hellmans agree)', async () => {
    // The browser-side counterpart of the Go test that re-derives pub from d: a scalar that did not
    // match its point would make these disagree, and every seal and open would fail quietly.
    const a = await identity('A')
    const bv = byLabel('B')
    const bPriv = await importPrivateKey(TEAM_NAMES_SUITE, hex(bv.private_key), hex(bv.public_key))
    const ab = await crypto.subtle.deriveBits({ name: 'ECDH', public: await importPublicKey(TEAM_NAMES_SUITE, hex(bv.public_key)) }, a.privateKey, 256)
    const ba = await crypto.subtle.deriveBits({ name: 'ECDH', public: await importPublicKey(TEAM_NAMES_SUITE, a.publicKey) }, bPriv, 256)
    expect(toHex(new Uint8Array(ab))).toBe(toHex(new Uint8Array(ba)))
  })

  it.each(v.envelope_negatives.map((n) => [n.description, n] as const))('refuses %s', async (_d, n) => {
    const vault = vaultOpsFor(await vaultKey(n.vmk))
    await expect(vault.open(n.context, hex(byLabel(n.envelope_of).sealed_private_key))).rejects.toThrow()
    if (n.context === IDENTITY_CONTEXT) {
      await expect(openIdentityEnvelope(vault, hex(byLabel(n.envelope_of).sealed_private_key))).rejects.toMatchObject({
        code: 'team_names/identity_unopenable',
      })
    }
  })
})

describe('the ten seals', () => {
  it.each(v.seals.map((s, i) => [i, s.description, s] as const))('seal %i (%s): info, plaintext, tag and every byte of the row', async (_i, _d, s) => {
    expect(toHex(nameInfo(s.team_id, s.sender_id, s.recipient_id))).toBe(s.info)
    expect(toHex(new TextEncoder().encode(s.name))).toBe(s.name_utf8)
    expect(toHex(padName(s.name))).toBe(s.plaintext)

    const sender = await identity(s.sender)
    const recipient = byLabel(s.recipient)
    expect(toHex(sender.keyId)).toBe(s.sender_key_id)
    expect(toHex(await keyIdOf(hex(recipient.public_key)))).toBe(s.recipient_key_id)

    const ephemeral = {
      privateKey: await importPrivateKey(TEAM_NAMES_SUITE, hex(s.ephemeral_private_key), hex(s.enc)),
      publicKey: hex(s.enc),
    }
    const out = await sealNameWithEphemeralKeyForTesting(
      {
        teamId: s.team_id,
        senderId: s.sender_id,
        recipientId: s.recipient_id,
        name: s.name,
        sender,
        recipientPublicKey: hex(recipient.public_key),
        recipientKeyId: hex(s.recipient_key_id),
      },
      ephemeral,
    )
    expect(toHex(out.trace.sharedSecret)).toBe(s.shared_secret)
    expect(toHex(out.trace.key)).toBe(s.key)
    expect(toHex(out.trace.baseNonce)).toBe(s.base_nonce)
    expect(toHex(out.enc)).toBe(s.enc)
    expect(toHex(out.sealed)).toBe(s.sealed)
    expect(out.sealed.length).toBe(SEALED_SIZE)
    expect(toHex(out.nameTag)).toBe(s.name_tag)

    const tagKey = await importTagKey(hex(byLabel(s.sender).tag_secret))
    expect(toHex(await nameTag(tagKey, s.name, hex(s.recipient_key_id), hex(s.enc)))).toBe(s.name_tag)
  })

  it.each(v.seals.map((s, i) => [i, s] as const))('seal %i opens for its recipient to the name', async (_i, s) => {
    const name = await openName({
      teamId: s.team_id,
      senderId: s.sender_id,
      recipientId: s.recipient_id,
      sealed: hex(s.sealed),
      recipient: await identity(s.recipient),
      senderPublicKey: hex(byLabel(s.sender).public_key),
    })
    expect(name).toBe(s.name)
  })
})

describe('the negative vectors', () => {
  it.each(v.open_negatives.map((n) => [n.description, n] as const))('%s', async (_d, n) => {
    const attempt = openName({
      teamId: n.team_id,
      senderId: n.sender_id,
      recipientId: n.recipient_id,
      sealed: hex(n.sealed),
      recipient: await identity(n.opener),
      senderPublicKey: hex(n.sender_public_key),
    })
    switch (n.outcome) {
      case 'open_fails':
        await expect(attempt).rejects.toMatchObject({ code: 'team_names/open_failed' })
        break
      case 'refused_version':
        await expect(attempt).rejects.toMatchObject({ code: 'team_names/unsupported_version' })
        break
      case 'refused_length':
        await expect(attempt).rejects.toMatchObject({ code: 'team_names/malformed' })
        break
      case 'no_name':
        await expect(attempt).resolves.toBeNull()
        break
    }
  })

  it.each(v.tag_negatives.map((n) => [n.description, n] as const))('the tag differs for %s', async (_d, n) => {
    const tag = await nameTag(await importTagKey(hex(n.tag_secret)), n.name, hex(n.recipient_key_id), hex(n.enc))
    expect(toHex(tag)).not.toBe(v.seals[n.row].name_tag)
  })

  it('refuses an unknown version byte and a wrong size before any cryptography', async () => {
    const s = v.seals[0]
    const recipient = await identity(s.recipient)
    const derive = vi.spyOn(crypto.subtle, 'deriveBits')
    const importKey = vi.spyOn(crypto.subtle, 'importKey')
    const v2 = hex(s.sealed)
    v2[0] = 0x02
    const params = { teamId: s.team_id, senderId: s.sender_id, recipientId: s.recipient_id, recipient, senderPublicKey: hex(byLabel(s.sender).public_key) }
    await expect(openName({ ...params, sealed: v2 })).rejects.toMatchObject({ code: 'team_names/unsupported_version' })
    await expect(openName({ ...params, sealed: hex(s.sealed).slice(0, 100) })).rejects.toMatchObject({ code: 'team_names/malformed' })
    expect(derive).not.toHaveBeenCalled()
    expect(importKey).not.toHaveBeenCalled()
  })
})

describe('the name as untrusted input', () => {
  it('strips controls, format characters, separators and default-ignorables, then NFC, then trims', () => {
    expect(cleanName('  Ada  ')).toBe('Ada')
    expect(cleanName('A\u0000d\u001fa\u007f\u0085')).toBe('Ada')
    // Bidi overrides and isolates: a name must not reorder the row it sits in.
    expect(cleanName('Ma‮rot‬')).toBe('Marot')
    expect(cleanName('⁦Eve⁩ ‪x‭')).toBe('Eve x')
    // Zero-width characters, the joiners, the BOM and the soft hyphen hide text.
    expect(cleanName('E​v‌‍e‎‏﻿­')).toBe('Eve')
    // Line and paragraph separators, Hangul fillers, the grapheme joiner, a variation selector.
    expect(cleanName('A B Cㅤᅟ͏️')).toBe('ABC')
    // NFC: e + combining acute becomes é.
    expect(cleanName('Zé')).toBe('Zé')
    expect(cleanName('Zé')?.length).toBe(2)
  })

  it('treats a name of nothing but invisible characters as no name', () => {
    for (const blank of ['', '   ', '​‏', 'ㅤㅤ', '‮ ‬', '﻿']) {
      expect(cleanName(blank)).toBeNull()
      expect(shareableName(blank)).toEqual({ kind: 'none' })
    }
    expect(shareableName(undefined)).toEqual({ kind: 'none' })
    expect(shareableName(null)).toEqual({ kind: 'none' })
  })

  it('shares at most 400 bytes of UTF-8, measured after cleaning', () => {
    expect(shareableName('é'.repeat(200))).toEqual({ kind: 'name', name: 'é'.repeat(200) })
    expect(shareableName('é'.repeat(200) + 'x')).toEqual({ kind: 'too_long' })
    expect(shareableName(`${'a'.repeat(400)}​​`)).toEqual({ kind: 'name', name: 'a'.repeat(400) })
    expect(() => padName('a'.repeat(401))).toThrow(TeamNamesError)
    expect(() => padName('')).toThrow(TeamNamesError)
  })

  it('cleans on open too, and keeps markup as its characters', async () => {
    const a = await identity('A')
    const bv = byLabel('B')
    const b = await identity('B')
    const s = v.seals[0]
    for (const [sent, shown] of [['﻿Ada‮', 'Ada'], ['<b>Ada</b> & "co"', '<b>Ada</b> & "co"']] as const) {
      const { sealed } = await sealName({
        teamId: s.team_id, senderId: s.sender_id, recipientId: s.recipient_id, name: sent, sender: a,
        recipientPublicKey: hex(bv.public_key), recipientKeyId: hex(bv.key_id),
      })
      await expect(openName({ teamId: s.team_id, senderId: s.sender_id, recipientId: s.recipient_id, sealed, recipient: b, senderPublicKey: a.publicKey })).resolves.toBe(shown)
    }
  })

  it('decodes the padding strictly', () => {
    const ok = padName('Ada')
    expect(unpadName(ok)).toBe('Ada')
    const nonZero = padName('Ada')
    nonZero[PADDED_SIZE - 1] = 1
    const tooLong = new Uint8Array(PADDED_SIZE)
    tooLong[0] = 0x01
    tooLong[1] = 0x91 // 401
    const badUtf8 = new Uint8Array(PADDED_SIZE)
    badUtf8.set([0x00, 0x02, 0xc3, 0x28])
    for (const bad of [nonZero, tooLong, badUtf8, new Uint8Array(PADDED_SIZE), ok.slice(0, 511)]) expect(unpadName(bad)).toBeNull()
  })

  it('folds names for the duplicate check across case, width and ß', () => {
    expect(nameFoldKey('Ada Lovelace')).toBe(nameFoldKey('ADA  LOVELACE'))
    expect(nameFoldKey('Ada')).toBe(nameFoldKey('Ａｄａ'))
    expect(nameFoldKey('Straße')).toBe(nameFoldKey('STRASSE'))
    expect(nameFoldKey('Ada')).not.toBe(nameFoldKey('Eve'))
  })
})

describe('ids', () => {
  it('takes canonical UUIDs only', () => {
    expect(toHex(uuidBytes('A1A1A1A1-0000-4000-8000-000000000001'))).toBe('a1a1a1a1000040008000000000000001')
    for (const bad of ['a1a1a1a1000040008000000000000001', 'a1a1a1a1-0000-4000-8000-00000000001', '../x', '']) {
      expect(() => uuidBytes(bad)).toThrow(TeamNamesError)
    }
  })
})

describe('creating a key', () => {
  it('seals a 219-byte envelope that opens to the same key, kept non-extractable', async () => {
    const vmk = await crypto.subtle.importKey('raw', crypto.getRandomValues(new Uint8Array(32)), 'HKDF', false, ['deriveKey'])
    const vault = vaultOpsFor(vmk as VaultKey)
    const { identity: created, envelope } = await createIdentity(vault)
    expect(envelope.length).toBe(IDENTITY_ENVELOPE_SIZE)
    expect(created.privateKey.extractable).toBe(false)
    const reopened = await openIdentityEnvelope(vault, envelope)
    expect(toHex(reopened.publicKey)).toBe(toHex(created.publicKey))
    expect(toHex(reopened.keyId)).toBe(toHex(await keyIdOf(created.publicKey)))

    // A created key seals to and opens from another created key.
    const other = (await createIdentity(vault)).identity
    const team = v.seals[0].team_id
    const [me, them] = [v.identities[0].user_id, v.identities[1].user_id]
    const { sealed } = await sealName({ teamId: team, senderId: me, recipientId: them, name: 'Ada', sender: created, recipientPublicKey: other.publicKey, recipientKeyId: other.keyId })
    await expect(openName({ teamId: team, senderId: me, recipientId: them, sealed, recipient: other, senderPublicKey: reopened.publicKey })).resolves.toBe('Ada')
  })
})

describe('error messages', () => {
  it('carry the code and never the name (review L8)', async () => {
    const secret = 'Zoë Secretname'
    const errors: unknown[] = []
    await sealName({
      teamId: 'nope', senderId: v.identities[0].user_id, recipientId: v.identities[1].user_id, name: secret,
      sender: await identity('A'), recipientPublicKey: hex(byLabel('B').public_key), recipientKeyId: hex(byLabel('B').key_id),
    }).catch((e: unknown) => errors.push(e))
    try {
      padName(secret.repeat(40))
    } catch (e) {
      errors.push(e)
    }
    const s = v.seals[3]
    const flipped = hex(s.sealed)
    flipped[200] ^= 1
    await openName({ teamId: s.team_id, senderId: s.sender_id, recipientId: s.recipient_id, sealed: flipped, recipient: await identity(s.recipient), senderPublicKey: hex(byLabel(s.sender).public_key) })
      .catch((e: unknown) => errors.push(e))
    expect(errors).toHaveLength(3)
    for (const e of errors) {
      expect(e).toBeInstanceOf(TeamNamesError)
      const err = e as TeamNamesError
      expect(err.message).toBe(err.code)
      expect(`${err.message} ${err.stack ?? ''}`).not.toContain('Secretname')
      expect(`${err.message} ${err.stack ?? ''}`).not.toContain(s.name)
    }
  })
})
